import { GameTask } from './GameTask';
import { GameStateKey } from '../states/GameStateKey';
import EagleTracker from '../tracking/EagleTracker';
import type { SlotRoundResult } from '../models/SlotRound';
import { WinTier } from '../config/GameConst';
import PresentationStore from '../config/PresentationStore';
import { finishSpin } from './FinishSpinTask';
import { endSpin } from './EndSpinTask';
import { playWinAnimationIfNeeded } from './WinAnimationTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * 免費遊戲結束收尾（流程任務與 GameMain 收尾邏輯合併）。
 */
export class ExitFreeGameTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly result: SlotRoundResult,
        private readonly spinWin: number
    ) {
        super();
    }

    protected onStart(): void {
        this.run()
            .catch((error) => console.warn('[ExitFreeGameTask] failed', error))
            .finally(() => this.finish());
    }

    private async run(): Promise<void> {
        const game = this.game;
        const spinWin = this.spinWin;

        finishSpin(game, this.result, spinWin);
        game.fgTotalWin = spinWin;

        // 原 GameMain_1001.exitFreeGame() 本體
        game.changeState(GameStateKey.NG);
        game.updateFgUi();
        game.applyGameModeUi(false);
        await game.playTransition('exit');
        console.log(`[FG] 結束，免費遊戲總贏分 = ${game.fgTotalWin}`);
        if (game.buyFeature.pendingBuyFeatureCost > 0) {
            const tracker = EagleTracker.getInstance();
            tracker.trackerTotalBet(game.buyFeature.pendingBuyFeatureCost);
            tracker.trackerTotalWin(game.fgTotalWin);
            tracker.skipAutoWin = false;
            game.buyFeature.pendingBuyFeatureCost = 0;
        }
        endSpin(game);

        // 回到 NG 報獎+Total
        if (!PresentationStore.getInstance().config.featureRoundWinPresentationEnabled) {
            await playWinAnimationIfNeeded(game, spinWin);
        }
        if (spinWin > 0) {
            const bet = game.storeManager.getModel('TemplateStore').betBalance;
            await game.popups.showWinAnimation(spinWin, bet, WinTier.TOTAL);
        }

        const jackpot = this.result.jackpot;
        if (jackpot?.won && jackpot.tier) {
            const amount = Number(jackpot.payout) || 0;
            console.log('[Jackpot][1001][FG] 觸發派獎', { tier: jackpot.tier, payout: jackpot.payout, amount });
            await game.popups.showJackpotOnAll(jackpot.tier, amount);
        }
    }
}
